import{z as o,x as A,o as t,c as d,q as s,j as l,D as e,d as E,s as n,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"图数据库","description":"","frontmatter":{"title":"图数据库","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/graph-db.md","filePath":"cs/graph-db.md","lastUpdated":1791063341000}'),p={name:"cs/graph-db.md"};function h(m,a,c,f,C,u){const B=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=s('<h1 id="图数据库" tabindex="-1">图数据库 <a class="header-anchor" href="#图数据库" aria-label="Permalink to &quot;图数据库&quot;">​</a></h1><div class="epigraph"><p>点与边是一等存储：多跳邻接用指针或邻接表，不是反复自连接。查询语言是遍历与模式匹配，优化器面对的是路径基数爆炸。</p><footer>—— 据 Angles and Gutierrez 图数据库；Neo4j/属性图实践；关系递归 CTE 对照</footer></div><p><a href="/cs/wide-column-bigtable">上一课</a>靠行键编码图会把边挤进单元格。本课把图当模型：属性图（点边带属性）或 RDF 三元组。缺口是访问：关系用递归 CTE 表达传递闭包，计划弱；图引擎邻接索引让 \\(k\\) 跳更自然，但基数估计更差。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多对多：关系用连接表，图用边记录。遍历：从点沿边过滤。缺口是<strong>爆炸</strong>：度高时 \\(k\\) 跳组合爆炸，必须限制、最短路算法、或预计算。<span class="marginnote">数字实例：平均度 \\(f=10\\) 时，3 跳的路径上限就是 \\(10^3=1000\\) 条，6 跳是 \\(10^6\\) 条——起点多几个，路径数就压过一张千万行的表。这是「限制遍历深度」成为图查询默认合同的算术原因。</span>事务：改边与点的原子，隔离下的幻边（间隙锁的图版）难。分片：图切会切断边，跨片多跳即分布式 shuffle 的最坏形状。</p><p>索引：点标签、边类型、属性 B+。全文与向量可挂在点上，后课。</p><p><span class="marginnote">Angles and Gutierrez 综述。SPARQL vs Cypher 点名。本课不教查询语法课。递归 CTE 课是关系侧对照。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>OLTP 图：局部遍历、事务。分析图：批量 Pregel/Giraph，另引擎。混合：图投影从关系 nightly 建，新鲜度合同像 HTAP。</p><p>与 ART：内存图可用邻接数组。与 LSM：边日志追加，读放大在邻居列表 compaction。</p>',10)),(t(),l(i,null,{default:e(()=>[n(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E7%82%B9%22%5D%20--%3E%20E%5B%22%E9%82%BB%E6%8E%A5%E8%BE%B9%22%5D%0A%20%20E%20--%3E%20V2%5B%22%E9%82%BB%E7%82%B9%22%5D%0A%20%20Q%5B%22k%20%E8%B7%B3%E6%A8%A1%E5%BC%8F%22%5D%20--%3E%20CARD%5B%22%E8%B7%AF%E5%BE%84%E5%9F%BA%E6%95%B0%E7%88%86%E7%82%B8%22%5D%0A%20%20CUT%5B%22%E5%9B%BE%E5%88%86%E7%89%87%22%5D%20--%3E%20XSH%5B%22%E8%B7%A8%E7%89%87%E5%A4%9A%E8%B7%B3%20shuffle%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[E("优化器：选择率在相关邻居上独立假设更假。物理：变长邻接、CSR 只读分析。"),r("span",{class:"marginnote"},"CSR（压缩稀疏行）翻译到图上就是：把所有点的邻居列表首尾相接拼成一个大数组，另存一张「每个点从哪一格开始」的目录。只读分析时它砍掉全部指针开销、缓存友好；代价是改一个点就得重排——所以它属于只读分析引擎，不属于 OLTP。"),E("锁：点级或边级，死锁沿环路径——WFG 仍用。")],-1)),(t(),l(i,null,{default:e(()=>[n(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E8%B5%B7%E7%82%B9%EF%BC%9A1%20%E4%B8%AA%22%5D%20--%3E%20H1%5B%221%20%E8%B7%B3%E5%90%8E%EF%BC%9Af%20%E4%B8%AA%E9%82%BB%E5%B1%85%22%5D%0A%20%20H1%20--%3E%20H2%5B%222%20%E8%B7%B3%E5%90%8E%EF%BC%9A%E7%BA%A6%20f%5E2%20%E6%9D%A1%E8%B7%AF%E5%BE%84%22%5D%0A%20%20H2%20--%3E%20HK%5B%22k%20%E8%B7%B3%E5%90%8E%EF%BC%9A%E7%BA%A6%20f%5Ek%20%E6%9D%A1%E8%B7%AF%E5%BE%84%22%5D%0A%20%20HK%20--%3E%20EST%5B%22%E4%BC%98%E5%8C%96%E5%99%A8%E6%8C%89%E7%8B%AC%E7%AB%8B%E5%81%87%E8%AE%BE%E4%BC%B0%E5%9F%BA%E6%95%B0%EF%BC%8C%E8%AF%AF%E5%B7%AE%E9%9A%8F%E8%B7%B3%E6%95%B0%E6%94%BE%E5%A4%A7%22%5D%0A%20%20HK%20--%3E%20CTRL%5B%22%E9%99%90%E6%B7%B1%20%2F%20%E5%8D%95%E6%BA%90%E6%9C%80%E7%9F%AD%E8%B7%AF%20%2F%20%E9%A2%84%E8%AE%A1%E7%AE%97%E9%97%AD%E5%8C%85%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p>关系对照：能用 SQL 几跳的不要上图库；图库赢在深度与变结构边类型。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲时序压缩。也不把知识图谱训练当数据库课。向量 ANN 下一课之后。</p><p>后课默认：多跳 OLTP 用图引擎或限制深度的 CTE；分片图要认切边。时序数据库：时间为主键，压缩与保留策略第一。</p><p>图切分是 NP 难启发式，生产靠业务分区（租户）少切。<span class="marginnote">直觉类比：图切像把社交网络按「住哪个城市」分库——同城好友在一个库里查得飞快，跨城好友的边却被切断，查一次「朋友的朋友」就要跨库跑一趟网络。所以生产上按租户这类天然聚类分片，让被切的边尽量少。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>属性图让遍历成为原生访问路径；k 跳基数难估。</li><li>分片切断边；分析图常用批量框架。</li><li>时序数据库下一课。</li><li>出处：Angles and Gutierrez；递归 CTE 对照。</li></ul>',7))])}const _=o(p,[["render",h]]);export{D as __pageData,_ as default};
